pp(24,C('c_0=0, c_1=1, c_n=c_(n−1)+c_(n−2) for n≥2','c_n=2c_(n−1)','c_n=1/n!',label='(a) Coefficient recurrence'),F(((1+S.sqrt(5))/2)**n/S.sqrt(5)-((1-S.sqrt(5))/2)**n/S.sqrt(5),'(b) Fibonacci formula'),N((S.sqrt(5)-1)/2,'Radius of convergence'),why='Multiply by1−x−x² and compare coefficients; factor the denominator to expand two geometric series. The nearest pole is(√5−1)/2.',limited=True)
